    (forall a, ASHADOW_BASE + (bv_unsigned sp0 - 128 - 65536) / 8 <= a < ASHADOW_BASE + 2^44 -> M (Z_to_bv 64 a) = Some (Z_to_bv 8 0)) ->
    know_ok RSEGS (ENV vals) M kn -> know_ok RSEGS (ENV vals) M (kn_readd lo hi kn).
