Scheme kc__11 := Elimination for OSSVerify.Proofs.boost_beast.http_request.lib.Bo.AsFprintfS_usage.fpPost Sort Prop.

  Theorem as_usage_tail : forall regs msF mo,
    P <= 131071 ->
    getr regs 2 = spm -> getr regs 4 = Z_to_bv 64 0x6617f0 -> getr regs 8 = Z_to_bv 64 2 -> getr regs 11 = Z_to_bv 64 (bv_unsigned sp0 + 8) ->
    lzok RSEGS L S Zr (mkCfg msF mo) -> same_but_materialized mo0 mo ->
    restrict L S msF = mkst regs (Z_to_bv 64 0xa4134) mem0 (seg_rom RSEGS) ->
